INSERT INTO grammar.content_catalog_topics(version,slug,catalog_hash,payload) VALUES('core-2026-09-v3','reporting-verb-patterns','e49c6c64b6333354230b05b223ded19e0e7519c1828bf3f36aee778f9f3f39c4','{"slug":"reporting-verb-patterns","title":"Reporting verbs and their complements","level":"C1","order":60,"summary":"Match the reporting verb to an infinitive, an -ing clause, an object or a preposition.","guidance":"Read the form and meaning together. Study the contrasts, then explain a worked example in your own words before starting a fresh practice session.","learningGoals":["Verb plus to-infinitive","Verb plus object and infinitive","Verb plus -ing","Prepositions before -ing"],"rules":[{"title":"Verb plus to-infinitive","explanation":"Agree, offer, promise and refuse commonly take a to-infinitive when reporting someone’s intended action. The understood subject of the infinitive is usually the reporting subject. The choice of reporting verb adds information about the speaker’s attitude.","pattern":"She **offered to help**. / They **refused to leave**.","commonMistakes":["Offered helping is not the ordinary pattern when offering to perform an action."],"examples":["“She promised **to prepare** the visitor guide before lunch.”","“She promised **to restore** the old portrait before lunch.”"],"skill":"form"},{"title":"Verb plus object and infinitive","explanation":"Advise, encourage, remind and warn can take an object followed by a to-infinitive. The object names the person expected to do the action. This differs from promise to, where the subject makes a commitment about their own action.","pattern":"He **reminded me to call**.","commonMistakes":["He reminded to call omits the person object required by this pattern."],"examples":["“He reminded us **to prepare** the visitor guide before leaving.”","“He reminded us **to restore** the old portrait before leaving.”"],"skill":"meaning"},{"title":"Verb plus -ing","explanation":"Admit, deny and suggest can take an -ing clause. They can also have other complements, such as a that-clause. Suggest does not normally use the same object + to-infinitive pattern as advise.","pattern":"She **admitted leaving**. / He **suggested waiting**.","commonMistakes":["Suggested me to wait is not the standard pattern; use suggested that I wait or advised me to wait."],"examples":["“They admitted **preparing** the visitor guide without permission.”","“They admitted **restoring** the old portrait without permission.”"],"skill":"contrast"},{"title":"Prepositions before -ing","explanation":"Some reporting verbs use a preposition: apologise for, insist on, accuse someone of. A verb after that preposition normally takes -ing. Keep any object required by the reporting verb.","pattern":"They **apologised for arriving** late.","commonMistakes":["Apologised to arrive changes or breaks the pattern; the reason for the apology follows for."],"examples":["“We apologised for **preparing** the visitor guide late.”","“We apologised for **restoring** the old portrait late.”"],"skill":"application"}],"tips":[],"source":"seed","provenance":{"kind":"original-guidance-aligned","referenceIds":["bc-reporting-patterns"],"version":"core-2026-09-v3","reviewStatus":"automated-checked; educator-review-pending"},"quizItems":[{"id":"9b29d6f1-5de1-58fd-a072-77a5df7ac44d","topicSlug":"reporting-verb-patterns","level":"C1","prompt":"“She promised ____ the visitor guide before lunch.”","choices":[{"id":"A","text":"prepared"},{"id":"B","text":"to prepare"},{"id":"C","text":"preparing"},{"id":"D","text":"prepare"}],"answerId":"B","hint":"The reporting verb **promise** takes a **to-infinitive** for the promised action.","explanation":"**Promise to prepare** reports her commitment to perform the action.","keywords":["promise-infinitive"],"skill":"promise-infinitive","contextKey":"reporting-verb-patterns-1","fingerprint":"86d48a86c1efe2c3d0b5f600aaa386b0e3252d30dbc3f2d208bbb979eefa1385","source":"seed","provenance":{"kind":"original-guidance-aligned","referenceIds":["bc-reporting-patterns"],"version":"core-2026-09-v3","reviewStatus":"automated-checked; educator-review-pending"},"teaching":{"steps":["The reporting verb **promise** takes a **to-infinitive** for the promised action.","**Promise to prepare** reports her commitment to perform the action.","Choose **to prepare**. Read the complete sentence again and check both its form and its intended meaning."],"choiceReasons":{"A":"A past form cannot serve as the infinitive complement.","B":"**Promise to prepare** reports her commitment to perform the action.","C":"Promise does not normally take this bare -ing complement for a commitment.","D":"Promise needs to before the infinitive in this pattern."}}},{"id":"0bbeab27-2def-5f71-a687-0078af544d97","topicSlug":"reporting-verb-patterns","level":"C1","prompt":"“He reminded us ____ the visitor guide before leaving.”","choices":[{"id":"A","text":"preparing"},{"id":"B","text":"prepare"},{"id":"C","text":"that prepare"},{"id":"D","text":"to prepare"}],"answerId":"D","hint":"Use **remind + person + to-infinitive**.","explanation":"**Reminded us to prepare** names us as the people expected to act.","keywords":["remind-object-infinitive"],"skill":"remind-object-infinitive","contextKey":"reporting-verb-patterns-1","fingerprint":"410fb157531f6155d5917985a895c7eb2c98d9d7c60dc2e268e79efed5c400a8","source":"seed","provenance":{"kind":"original-guidance-aligned","referenceIds":["bc-reporting-patterns"],"version":"core-2026-09-v3","reviewStatus":"automated-checked; educator-review-pending"},"teaching":{"steps":["Use **remind + person + to-infinitive**.","**Reminded us to prepare** names us as the people expected to act.","Choose **to prepare**. Read the complete sentence again and check both its form and its intended meaning."],"choiceReasons":{"A":"Remind + person takes a to-infinitive here, not bare -ing.","B":"The to marker is required in this pattern.","C":"That would need a finite clause with its own subject.","D":"**Reminded us to prepare** names us as the people expected to act."}}},{"id":"ce7440d1-8aa1-575f-a0af-b5ae54376198","topicSlug":"reporting-verb-patterns","level":"C1","prompt":"“They admitted ____ the visitor guide without permission.”","choices":[{"id":"A","text":"prepare"},{"id":"B","text":"prepared"},{"id":"C","text":"preparing"},{"id":"D","text":"to prepare"}],"answerId":"C","hint":"After **admit**, this action is expressed by an **-ing clause**.","explanation":"**Admitted preparing** uses an -ing complement for the acknowledged action.","keywords":["admit-gerund"],"skill":"admit-gerund","contextKey":"reporting-verb-patterns-1","fingerprint":"4ee67b6ed50c2f35d11a602d35aba72f7799e6d6fdb079fa9d561164b578f05d","source":"seed","provenance":{"kind":"original-guidance-aligned","referenceIds":["bc-reporting-patterns"],"version":"core-2026-09-v3","reviewStatus":"automated-checked; educator-review-pending"},"teaching":{"steps":["After **admit**, this action is expressed by an **-ing clause**.","**Admitted preparing** uses an -ing complement for the acknowledged action.","Choose **preparing**. Read the complete sentence again and check both its form and its intended meaning."],"choiceReasons":{"A":"A bare base verb does not complete admit here.","B":"A simple past form cannot serve as this non-finite complement.","C":"**Admitted preparing** uses an -ing complement for the acknowledged action.","D":"Admit in this construction takes -ing, not a to-infinitive."}}},{"id":"9e28f1f5-c060-5866-a764-f587ac201ffe","topicSlug":"reporting-verb-patterns","level":"C1","prompt":"“We apologised for ____ the visitor guide late.”","choices":[{"id":"A","text":"prepare"},{"id":"B","text":"prepared"},{"id":"C","text":"preparing"},{"id":"D","text":"to prepare"}],"answerId":"C","hint":"The key is the **preposition for**, which is followed by a noun or -ing form.","explanation":"After preposition **for**, use **preparing** to name the action being apologised for.","keywords":["apologise-preposition"],"skill":"apologise-preposition","contextKey":"reporting-verb-patterns-1","fingerprint":"364766ec2494874a54fa546826a68c648119ef8c65a15e036e024656eda20eed","source":"seed","provenance":{"kind":"original-guidance-aligned","referenceIds":["bc-reporting-patterns"],"version":"core-2026-09-v3","reviewStatus":"automated-checked; educator-review-pending"},"teaching":{"steps":["The key is the **preposition for**, which is followed by a noun or -ing form.","After preposition **for**, use **preparing** to name the action being apologised for.","Choose **preparing**. Read the complete sentence again and check both its form and its intended meaning."],"choiceReasons":{"A":"A base verb is not the standard complement after for here.","B":"A past form is not the -ing clause required after for.","C":"After preposition **for**, use **preparing** to name the action being apologised for.","D":"A to-infinitive cannot follow for in this action-complement pattern."}}},{"id":"b791a218-b247-5c7d-a303-39def343a44e","topicSlug":"reporting-verb-patterns","level":"C1","prompt":"“She promised ____ the old portrait before lunch.”","choices":[{"id":"A","text":"restore"},{"id":"B","text":"restored"},{"id":"C","text":"to restore"},{"id":"D","text":"restoring"}],"answerId":"C","hint":"The reporting verb **promise** takes a **to-infinitive** for the promised action.","explanation":"**Promise to restore** reports her commitment to perform the action.","keywords":["promise-infinitive"],"skill":"promise-infinitive","contextKey":"reporting-verb-patterns-2","fingerprint":"6b2a719b02d4c2e3f4613a582a3613bdc15a8d2f226897e973bc96840955d042","source":"seed","provenance":{"kind":"original-guidance-aligned","referenceIds":["bc-reporting-patterns"],"version":"core-2026-09-v3","reviewStatus":"automated-checked; educator-review-pending"},"teaching":{"steps":["The reporting verb **promise** takes a **to-infinitive** for the promised action.","**Promise to restore** reports her commitment to perform the action.","Choose **to restore**. Read the complete sentence again and check both its form and its intended meaning."],"choiceReasons":{"A":"Promise needs to before the infinitive in this pattern.","B":"A past form cannot serve as the infinitive complement.","C":"**Promise to restore** reports her commitment to perform the action.","D":"Promise does not normally take this bare -ing complement for a commitment."}}},{"id":"491a7cae-3e1a-52e2-a153-1f4db42eb888","topicSlug":"reporting-verb-patterns","level":"C1","prompt":"“He reminded us ____ the old portrait before leaving.”","choices":[{"id":"A","text":"restore"},{"id":"B","text":"that restore"},{"id":"C","text":"to restore"},{"id":"D","text":"restoring"}],"answerId":"C","hint":"Use **remind + person + to-infinitive**.","explanation":"**Reminded us to restore** names us as the people expected to act.","keywords":["remind-object-infinitive"],"skill":"remind-object-infinitive","contextKey":"reporting-verb-patterns-2","fingerprint":"7b0d3766580c2160a4cc8d9643ae9ecf2c29897dc967c4f59d43e28fd7bb429b","source":"seed","provenance":{"kind":"original-guidance-aligned","referenceIds":["bc-reporting-patterns"],"version":"core-2026-09-v3","reviewStatus":"automated-checked; educator-review-pending"},"teaching":{"steps":["Use **remind + person + to-infinitive**.","**Reminded us to restore** names us as the people expected to act.","Choose **to restore**. Read the complete sentence again and check both its form and its intended meaning."],"choiceReasons":{"A":"The to marker is required in this pattern.","B":"That would need a finite clause with its own subject.","C":"**Reminded us to restore** names us as the people expected to act.","D":"Remind + person takes a to-infinitive here, not bare -ing."}}},{"id":"81e45a94-857e-55cf-a550-c0febac94bd6","topicSlug":"reporting-verb-patterns","level":"C1","prompt":"“They admitted ____ the old portrait without permission.”","choices":[{"id":"A","text":"restored"},{"id":"B","text":"restoring"},{"id":"C","text":"to restore"},{"id":"D","text":"restore"}],"answerId":"B","hint":"After **admit**, this action is expressed by an **-ing clause**.","explanation":"**Admitted restoring** uses an -ing complement for the acknowledged action.","keywords":["admit-gerund"],"skill":"admit-gerund","contextKey":"reporting-verb-patterns-2","fingerprint":"c76587894a48aeda4f8b35f9040f6db7520098e48a4a4586bf2c3ff47e3b5980","source":"seed","provenance":{"kind":"original-guidance-aligned","referenceIds":["bc-reporting-patterns"],"version":"core-2026-09-v3","reviewStatus":"automated-checked; educator-review-pending"},"teaching":{"steps":["After **admit**, this action is expressed by an **-ing clause**.","**Admitted restoring** uses an -ing complement for the acknowledged action.","Choose **restoring**. Read the complete sentence again and check both its form and its intended meaning."],"choiceReasons":{"A":"A simple past form cannot serve as this non-finite complement.","B":"**Admitted restoring** uses an -ing complement for the acknowledged action.","C":"Admit in this construction takes -ing, not a to-infinitive.","D":"A bare base verb does not complete admit here."}}},{"id":"84c67cc6-13d1-5ed5-a0db-886a2f368169","topicSlug":"reporting-verb-patterns","level":"C1","prompt":"“We apologised for ____ the old portrait late.”","choices":[{"id":"A","text":"to restore"},{"id":"B","text":"restore"},{"id":"C","text":"restored"},{"id":"D","text":"restoring"}],"answerId":"D","hint":"The key is the **preposition for**, which is followed by a noun or -ing form.","explanation":"After preposition **for**, use **restoring** to name the action being apologised for.","keywords":["apologise-preposition"],"skill":"apologise-preposition","contextKey":"reporting-verb-patterns-2","fingerprint":"b91ee95bbf3a2ba180326f5b30fcfdc5fee0ac9974a4d9e258c8d19c6620a618","source":"seed","provenance":{"kind":"original-guidance-aligned","referenceIds":["bc-reporting-patterns"],"version":"core-2026-09-v3","reviewStatus":"automated-checked; educator-review-pending"},"teaching":{"steps":["The key is the **preposition for**, which is followed by a noun or -ing form.","After preposition **for**, use **restoring** to name the action being apologised for.","Choose **restoring**. Read the complete sentence again and check both its form and its intended meaning."],"choiceReasons":{"A":"A to-infinitive cannot follow for in this action-complement pattern.","B":"A base verb is not the standard complement after for here.","C":"A past form is not the -ing clause required after for.","D":"After preposition **for**, use **restoring** to name the action being apologised for."}}},{"id":"5fa35b04-f3d4-5d75-a253-b6d926ce54de","topicSlug":"reporting-verb-patterns","level":"C1","prompt":"“She promised ____ the garden fence before lunch.”","choices":[{"id":"A","text":"measured"},{"id":"B","text":"to measure"},{"id":"C","text":"measuring"},{"id":"D","text":"measure"}],"answerId":"B","hint":"The reporting verb **promise** takes a **to-infinitive** for the promised action.","explanation":"**Promise to measure** reports her commitment to perform the action.","keywords":["promise-infinitive"],"skill":"promise-infinitive","contextKey":"reporting-verb-patterns-3","fingerprint":"ca6c7048a380b0209893b9ba4de8d4319e1d5d0b75372af0a5e819840922d0b1","source":"seed","provenance":{"kind":"original-guidance-aligned","referenceIds":["bc-reporting-patterns"],"version":"core-2026-09-v3","reviewStatus":"automated-checked; educator-review-pending"},"teaching":{"steps":["The reporting verb **promise** takes a **to-infinitive** for the promised action.","**Promise to measure** reports her commitment to perform the action.","Choose **to measure**. Read the complete sentence again and check both its form and its intended meaning."],"choiceReasons":{"A":"A past form cannot serve as the infinitive complement.","B":"**Promise to measure** reports her commitment to perform the action.","C":"Promise does not normally take this bare -ing complement for a commitment.","D":"Promise needs to before the infinitive in this pattern."}}},{"id":"104f8288-8cf9-5fe5-a8a5-03696694e52f","topicSlug":"reporting-verb-patterns","level":"C1","prompt":"“He reminded us ____ the garden fence before leaving.”","choices":[{"id":"A","text":"measuring"},{"id":"B","text":"measure"},{"id":"C","text":"that measure"},{"id":"D","text":"to measure"}],"answerId":"D","hint":"Use **remind + person + to-infinitive**.","explanation":"**Reminded us to measure** names us as the people expected to act.","keywords":["remind-object-infinitive"],"skill":"remind-object-infinitive","contextKey":"reporting-verb-patterns-3","fingerprint":"207c47d9c473fd72687c95963869022d2d86f6237af89a70b1963513f0ed3bd9","source":"seed","provenance":{"kind":"original-guidance-aligned","referenceIds":["bc-reporting-patterns"],"version":"core-2026-09-v3","reviewStatus":"automated-checked; educator-review-pending"},"teaching":{"steps":["Use **remind + person + to-infinitive**.","**Reminded us to measure** names us as the people expected to act.","Choose **to measure**. Read the complete sentence again and check both its form and its intended meaning."],"choiceReasons":{"A":"Remind + person takes a to-infinitive here, not bare -ing.","B":"The to marker is required in this pattern.","C":"That would need a finite clause with its own subject.","D":"**Reminded us to measure** names us as the people expected to act."}}},{"id":"675fa9f0-49c9-54da-a286-e55a1ead16b5","topicSlug":"reporting-verb-patterns","level":"C1","prompt":"“They admitted ____ the garden fence without permission.”","choices":[{"id":"A","text":"measured"},{"id":"B","text":"measuring"},{"id":"C","text":"to measure"},{"id":"D","text":"measure"}],"answerId":"B","hint":"After **admit**, this action is expressed by an **-ing clause**.","explanation":"**Admitted measuring** uses an -ing complement for the acknowledged action.","keywords":["admit-gerund"],"skill":"admit-gerund","contextKey":"reporting-verb-patterns-3","fin