SELECT j->>'slug',j->>'title',j->>'level',(j->>'order')::integer,j->>'summary',j->>'guidance',ARRAY(SELECT jsonb_array_elements_text(j->'learningGoals')),j->'rules',ARRAY(SELECT jsonb_array_elements_text(j->'tips')),'seed','{"kind":"original-guidance-aligned","referenceIds":["bc-reporting-patterns"],"version":"core-2026-09-v3","reviewStatus":"automated-checked; educator-review-pending","contentHash":"e49c6c64b6333354230b05b223ded19e0e7519c1828bf3f36aee778f9f3f39c4","sources":[{"id":"bc-reporting-patterns","title":"Patterns with reporting verbs","url":"https://learnenglish.britishcouncil.org/free-resources/grammar/c1/patterns-reporting-verbs","publisher":"British Council LearnEnglish","use":"Grammar guidance and scope only. Original explanations and practice; no publisher exercise reproduced.","reviewedOn":"2026-09-13"}]}'::jsonb FROM (SELECT payload j FROM grammar.content_catalog_topics WHERE version='core-2026-09-v3' AND slug='reporting-verb-patterns') p
