 IF NOT EXISTS(SELECT 1 FROM grammar.content_catalog_topics WHERE version='core-2026-09-v3' AND slug='reporting-verb-patterns' AND payload_md5='4ec924f19e0674ef1b9052275fd61b72') THEN RAISE EXCEPTION 'Full payload mismatch'; END IF;
 IF (SELECT count(*) FROM grammar.grammar_quiz_items WHERE topic_slug='reporting-verb-patterns')<>200 THEN RAISE EXCEPTION 'Question count mismatch'; END IF;
